    content: `Omega-3-Fettsäuren gehören zu den am besten untersuchten Nährstoffen, wenn es um Haut- und Fellgesundheit beim Hund geht. Kein Wunder, dass Lachsöl in fast jedem Hundehaushalt steht. Aber weißt du auch, warum es wirkt, welche Quellen wirklich gut sind und wie viel davon sinnvoll ist?

## Was Omega-3 im Körper macht

Omega-3-Fettsäuren — vor allem **EPA** (Eicosapentaensäure) und **DHA** (Docosahexaensäure) — wirken auf Zellmembranen. Sie machen Zellen geschmeidiger und haben eine entzündungshemmende Wirkung im Körper. Für Haut und Fell bedeutet das:

- Die Haut wird **weniger trocken und schuppig**
- Chronische Entzündungsprozesse in der Haut werden gemildert
- Das Fell wirkt **satter und glänzender**
- Die Hautbarriere wird gestärkt, was die Anfälligkeit für Reizungen reduziert

## Die besten Quellen für marine Omega-3

Nicht alle Quellen sind gleich gut. Marine Quellen liefern EPA und DHA direkt in der vom Körper nutzbaren Form:

- **Lachsöl** — beliebt und gut verträglich
- **Heringsöl oder Sardinenöl** — günstig und hochwertig
- **Fettiger Fisch** als Hauptzutat im Nassfutter oder als Ergänzung

Pflanzliche Quellen wie Leinöl enthalten **ALA**, eine Vorstufe, die der Hund nur ineffizient in EPA und DHA umwandeln kann. Für die Fellwirkung sind marine Quellen daher deutlich effektiver.

## Das richtige Verhältnis: Omega-3 zu Omega-6

Hier liegt ein häufiger Fehler: Es kommt nicht nur auf Omega-3, sondern auch auf das **Verhältnis zu Omega-6** an. Viele kommerzielle Futter enthalten viel Omega-6 (z. B. aus Geflügelöl) und wenig Omega-3 — das fördert Entzündungsprozesse.

Ein gutes Verhältnis liegt idealerweise zwischen **5:1 und 10:1** (Omega-6 zu Omega-3). Überprüfe das Verhältnis auf der Futteranalyse, wenn du es optimieren möchtest.

## Dosierung: Weniger ist oft genug

Bei Lachsöl reicht oft schon **ein Teelöffel pro 10 kg Körpergewicht** täglich als Ergänzung. Zu viel Öl kann zu weichem Kot, Übelkeit oder einem Ungleichgewicht anderer Fettsäuren führen. Starte immer niedrig und erhöhe langsam.

**Wichtig:** Omega-3 aus Ölen ist empfindlich gegenüber Hitze und Licht. Kaufe Öl in dunklen Flaschen und öffne keine zu große Menge auf einmal.

## Wann du eine Verbesserung erwartest

Wie bei jeder Ernährungsänderung braucht das Fell Zeit. Plane **sechs bis acht Wochen** ein, bevor du beurteilst, ob die Ergänzung hilft. Die Wirkung zeigt sich am Glanz, an der Schuppen-Reduktion und am weicheren Griff.

## Häufige Fragen

### Ist Lachsöl oder Leinöl besser?
Für die Fellwirkung ist Lachsöl besser, da es EPA und DHA direkt liefert. Leinöl hat Vorteile für andere Körperfunktionen, die Fellwirkung ist aber geringer.

### Kann ich fettigen Fisch statt Öl füttern?
Ja, fettiger Fisch wie Hering, Makrele oder Lachs liefert Omega-3 direkt und ist eine vollwertige Quelle. Hier keine Gewürze, Zwiebeln oder Knoblauch — der Fisch pur oder als Teil eines kompletten Futters.

### Muss ich dauerhaft Öl ergänzen?
Das hängt vom Grundfutter ab. Ein Futter mit viel fettem Fisch ist oft selbst ausreichend versorgt. Wenn du trockenes Geflügelfutter fütterst, macht eine Ergänzung oft Sinn.

## Das Wichtigste in Kürze

- EPA und DHA aus marinen Quellen sind die wirksamsten Omega-3-Lieferanten für das Fell
- Lachsöl, Heringsöl und fettiger Fisch sind die besten Quellen
- Das Verhältnis Omega-6 zu Omega-3 ist mindestens so wichtig wie der absolute Gehalt
- Sechs bis acht Wochen Geduld nach dem Start einer Ergänzung einplanen`,
