    content: `Jede Bürstrunde ist eine Chance. Wenn du weißt, worauf du achten solltest, verwandelst du eine Routinepflege in einen wertvollen Gesundheitscheck — und erkennst Probleme, bevor sie groß werden.

## Was du beim Bürsten finden kannst

Der regelmäßige Blick ins Fell lohnt sich, denn du findest:

- **Zecken** — oft erst richtig sichtbar, wenn du das Fell auseinanderschiebst
- **Flöhe und Flohkot** — schwarze Krümel, die auf feuchtem Papier rötlich werden
- **Knoten und Verfilzungen** — bevor sie zu schmerzhaften Matten werden
- **Hautrötungen, Pusteln oder Schwellungen** — erste Zeichen von Entzündungen
- **Grannen** — eingedrungene Pflanzenteile, besonders nach Spaziergängen
- **Zunahmen oder Verdickungen** unter der Haut
- **Schuppen oder trockene Stellen**

Keiner dieser Befunde ersetzt den Tierarzt — aber früh zu entdecken gibt dir einen Vorsprung.

## Wie du den Check systematisch machst

Teile den Körper gedanklich in Abschnitte und arbeite sie ab:

1. **Kopf und Hals** — hinter den Ohren, am Kinn, Halsfalten
2. **Rücken und Seiten**
3. **Achseln** — besonders Zecken-anfällig
4. **Bauch und Leiste**
5. **Beine, Pfoten und zwischen den Zehen**
6. **Rute und Afterbereich**
7. **Ohrmuschel innen** (nur sehen, nicht einführen)

**Tipp:** Nutze bei dichtem oder dunklem Fell eine kleine Taschenlampe — du siehst deutlich mehr.

## Auf welche Signale du achten solltest

| Befund | Was es bedeuten könnte |
|---|---|
| Kleine dunkle Krümel | Flohkot — Flohbefall wahrscheinlich |
| Fest haftende Wucherung | Zecke — sofort entfernen |
| Runde, schuppige kahle Stelle | Hautpilz möglich |
| Rote, heiße Hautstelle | Entzündung — beobachten |
| Verhärtung unter der Haut | Abklären lassen |
| Stark riechendes Fell | Mögliche Hautterkrankung |

## Zecken richtig entfernen

Wenn du eine Zecke findest, entferne sie so früh wie möglich mit einer Zeckenzange oder -karte — nie mit Öl oder Klebstoff. Die Zecke eng am Hautniveau greifen, ruhig und gleichmäßig herausziehen, nicht drehen. Die Einstichstelle beobachten.

## Flohkot nachweisen

Wenn du schwarze Krümel findest, mach den Test: Einige Krümel auf feuchtes weißes Küchenpapier legen. Werden sie rötlich-braun, handelt es sich um verdautes Blut aus Flohkot — sicherer Nachweis eines Flohbefalls.

## Häufige Fragen

### Wie oft sollte ich den Körper komplett abtasten?
Mindestens einmal pro Woche beim Bürsten. In der Zeckensaison (Frühjahr bis Herbst) am besten täglich nach Spaziergängen.

### Was mache ich, wenn ich eine Beule unter der Haut entdecke?
Nicht ignorieren. Auch wenn die meisten Beulen harmlos sind (Talgdrüsenzysten, Lipome), gehören neue oder wachsende Zunahmen tierärztlich abgeklärt.

### Muss ich die Bürstroutine anpassen, wenn ich etwas gefunden habe?
Ja. Bei Flöhen z. B. die Bürste danach heiß waschen und den Schlafplatz behandeln. Bei aktiven Hautentzündungen die betroffene Stelle beim Bürsten aussparen, bis sie abgeklungen ist.

## Das Wichtigste in Kürze

- Jede Bürstrunde ist ein Gesundheitscheck — nutze diese Zeit bewusst
- Systematisch alle Körperstellen abarbeiten, besonders Achseln, Leiste und hinter Ohren
- Zecken, Flohkot, Hautrötungen und Knoten frühzeitig erkennen
- Befunde nicht ignorieren — früh entdeckt ist leichter behandelt`,
