    slug: "haarausfall-ernst-nehmen",
    title: "Haarausfall beim Hund ernst nehmen: Wann ist er krankhaft?",
    shortDescription:
      "Kahle Stellen sind nicht normal. Sie können von Parasiten, Allergien, Pilzen oder Hormonstörungen kommen — immer abklären.",
    level: 1,
    tags: ["haarausfall", "symptome", "parasiten", "diagnose"],
    imageUrl: "/images/tipps/fell-haut/18.jpg",
    imageAlt: "Kahle Stelle im Fell eines Hundes wird von einem Tierarzt untersucht",
    content: `Viel Haar auf dem Sofa im Fellwechsel ist normal. Kahle Stellen auf der Haut des Hundes sind es nicht. Wer die Unterschiede kennt und Frühzeichen erkennt, kann früh handeln — denn die Ursachen für krankhafte Kahlheit sind vielfältig und manchmal ernsthaft.

## Normales Haaren vs. krankhafter Haarausfall

**Normal:**
- Saisonaler Fellwechsel im Frühjahr und Herbst
- Gleichmäßige Reduktion ohne kahle Stellen
- Kein Juckreiz, keine Hautveränderungen

**Krankhaft:**
- **Kahle Stellen** — runde, ungleichmäßig berandete oder großflächige Bereiche ohne Fell
- Haarausfall **außerhalb der Wechselperioden**
- Haarausfall mit **Juckreiz, Rötung, Schuppen oder Geruch**
- **Symmetrischer Haarausfall** ohne Juckreiz (oft hormonell)
- Haarausfall, der sich **ausbreitet**

## Die häufigsten Ursachen für krankhaften Haarausfall

### Parasiten
- **Demodex-Milben** (Haarbalgmilben): Verursachen kahle, oft nicht juckende Stellen, häufig bei Welpen oder immungeschwächten Hunden
- **Sarcoptes-Milben** (Räude): Intensiver Juckreiz, Hautrötung, Haarverlust — hochansteckend
- **Flöhe und Flohspeichelallergie**: Haarausfall vor allem im Lendenbereich

### Hautpilz (Ringelflechte)
Kreisrunde, schuppige Kahlstellen, oft ohne starken Juckreiz. Auf Menschen übertragbar — dringend behandeln lassen.

### Allergien
Futter- oder Umweltallergien führen zu Juckreiz und durch ständiges Kratzen und Lecken zu sekundärem Haarausfall.

### Hormonelle Erkrankungen
- **Schilddrüsenunterfunktion**: Symmetrischer, diffuser Haarverlust, stumpfes Fell, Gewichtszunahme, Trägheit
- **Cushing-Syndrom**: Haarausfall, dünne Haut, Bauchvergrößerung, vermehrtes Trinken

### Narben und Verletzungen
Haut, die tief verletzt oder entzündet war, kann keine Haare mehr wachsen lassen.

## Was du beobachten solltest

Notiere beim Haarverlust:
- **Wo** genau (Rücken, Flanken, Kopf, symmetrisch?)
- **Wie** (mit oder ohne Juckreiz?)
- **Wie lange** (seit wann?)
- **Was sonst** ändert sich (Verhalten, Durst, Gewicht?)

Diese Informationen helfen dem Tierarzt erheblich bei der Eingrenzung.

## Häufige Fragen

### Kann Stress Haarausfall beim Hund verursachen?
In Maßen ja — chronischer Stress kann die Haut und das Immunsystem beeinflussen. Massiver, lokaler Haarausfall ist aber fast immer auf andere Ursachen zurückzuführen.

### Wächst Fell nach einer Behandlung wieder nach?
Das hängt von der Ursache ab. Bei erfolgreich behandelten Parasiten oder Hormonstörungen wächst das Fell oft vollständig nach — bei Narbengewebe nicht mehr.

### Wie lange bis zur Diagnose?
Manchmal reicht eine Untersuchung, manchmal braucht es Blutuntersuchungen, Hautgeschabsel oder Allergie-Ausschlussdiäten. Plane Zeit ein.

## Das Wichtigste in Kürze

- Kahle Stellen sind immer ein Anlass, genauer hinzuschauen
- Die häufigsten Ursachen sind Parasiten, Pilze, Allergien und Hormonstörungen
- Beobachtungen zu Lage, Art und Begleitsymptomen dem Tierarzt mitteilen
- Früh abklären — viele Ursachen sind gut behandelbar`,
