    title: "Juckreiz beim Hund nicht ignorieren: Ursachen und erste Schritte",
    shortDescription:
      "Ständiges Kratzen, Lecken und Beißen schädigt die Haut. Suche die Ursache, statt nur den Juckreiz zu unterdrücken.",
    level: 1,
    tags: ["juckreiz", "symptome", "pruritus", "diagnose"],
    imageUrl: "/images/tipps/fell-haut/1.jpg",
    imageAlt: "Hund kratzt sich intensiv am Hals mit dem Hinterlauf",
    content: `Gelegentliches Kratzen ist bei jedem Hund normal. Wenn dein Hund aber regelmäßig, ausdauernd oder heftig kratzt, beißt, leckt oder sich reibt — dann ist das ein Signal, das eine Antwort verdient.

## Warum Juckreiz ein Problem ist

Ständiger Juckreiz schadet auf mehreren Ebenen:

- **Die Haut wird durch Kratzen, Lecken und Beißen verletzt** — aufgekratzte Stellen entzünden sich leicht
- **Hot Spots** (nässende, akute Hautentzündungen) entstehen rasch
- **Sekundärinfektionen** mit Bakterien oder Hefepilzen folgen oft
- Der Hund schläft schlecht, ist unruhig und leidet

Juckreiz zu unterdrücken ohne die Ursache zu kennen, ist wie den Feuermelder abzuschalten, statt das Feuer zu löschen.

## Wo kratzt dein Hund?

Die Stelle gibt wichtige Hinweise:

| Ort des Juckreizes | Mögliche Ursache |
|---|---|
| Pfoten (lecken, knabbern) | Allergie (Futter oder Umwelt), Kontaktdermatitis |
| Ohren (schütteln, kratzen) | Ohrenentzündung, Allergie, Milben |
| Rücken nahe Rute | Flohspeichelallergie |
| Bauch und Achseln | Allergie, Hefepilz, Kontaktreizung |
| Ganzer Körper | Systemische Reaktion, starker Parasitenbefall |

## Die häufigsten Ursachen

### Parasiten
Flöhe, Milben (Sarcoptes, Cheyletiellen, Demodex), Läuse — immer der erste Ausschluss.

### Allergien
Futtermittel- oder Umweltallergie (Pollen, Hausstaubmilben, Gräser). Häufig saisonal oder ganzjährig.

### Kontaktdermatitis
Reaktion auf ein Material, ein Pflegeprodukt, Streusalz oder chemische Substanzen.

### Infektionen
Bakterielle Hautinfektionen (Pyodermie) oder Hefepilze (Malassezia) jucken stark.

### Trockene Haut
Besonders im Winter — Juckreiz ohne andere Veränderungen, oft mit Schuppen.

## Was du als erstes tun kannst

1. **Parasiten ausschließen** — Flohkot prüfen, Fell absuchen
2. **Wann begann es?** Gleichzeitig mit neuem Futter, neuer Decke, neuem Shampoo?
3. **Saisonal?** Nur im Sommer/Frühjahr? Verdacht auf Umweltallergie
4. **Tierarzt aufsuchen**, wenn der Juckreiz stark, anhaltend oder mit Hautveränderungen verbunden ist

## Häufige Fragen

### Darf ich meinem Hund bei Juckreiz ein Antihistaminikum geben?
Nur nach tierärztlicher Absprache. Manche menschlichen Antihistaminika sind für Hunde nicht geeignet oder in falscher Dosierung.

### Kann ich mit Cortisoncreme helfen?
Menschliche Cortisoncreme nicht verwenden. Kortison kann kurzfristig den Juckreiz lindern, löst aber keine Ursache und kann bei falscher Anwendung die Haut schädigen.

### Hilft Kokosnussöl gegen Juckreiz?
Kokosnussöl ist kein Medikament. Bei trockener Haut kann es milden Juckreiz lindern — bei einer Infektion oder Allergie hilft es nicht.

## Das Wichtigste in Kürze

- Anhaltender Juckreiz ist immer ein Signal — nicht einfach aushalten oder unterdrücken
- Ort des Juckreizes gibt erste Hinweise auf die Ursache
- Parasiten immer als erstes ausschließen
- Bei starkem oder anhaltendem Juckreiz: tierärztliche Diagnose ist unerlässlich`,
