    imageUrl: "/images/tipps/fell-haut/2.jpg",
    imageAlt: "Hund wird auf Parasiten im Fell untersucht",
    content: `Vor jeder aufwändigen Diagnose steht ein einfacher Check: Hat mein Hund Parasiten? Denn Flöhe, Milben und Läuse gehören zu den häufigsten Auslösern von Juckreiz, Haarausfall und Hautproblemen — und werden erstaunlich oft übersehen.

## Warum Parasiten immer zuerst ausgeschlossen werden sollten

Parasiten zu übersehen bedeutet:
- Die falsche Ursache behandeln
- Zeit und Geld für unnötige Tests und Therapien verschwenden
- Dem Hund weiter leiden lassen

Zudem sind manche Parasiten (Flöhe, Räudemilben, Hautpilz) auf Menschen oder andere Haustiere übertragbar — ein schneller Check schützt die ganze Familie.

## Die wichtigsten Parasiten und ihre Zeichen

### Flöhe
Die häufigsten externen Parasiten. Zeichen:
- **Flohkot** (schwarze Krümel im Fell, werden auf feuchtem Papier rötlich)
- Juckreiz besonders am **Rücken nahe der Rute**
- Hund springt beim Bürsten, sehr unruhig

Flöhe sieht man oft nicht direkt — der Kot ist der verlässlichere Beweis.

### Sarcoptes-Milben (Räude)
Sehr ansteckend, auch auf Menschen übertragbar. Zeichen:
- **Heftiger Juckreiz**, besonders nachts
- Rötliche, verkrustete Haut an **Ohrenrändern, Ellbogen, Pfoten**
- Schnell sich ausbreitende Kahlstellen
- Hund lässt sich kaum beruhigen

### Demodex-Milben (Haarbalgmilben)
Leben auf normaler Hundehaut, können sich bei Schwäche des Immunsystems vermehren. Zeichen:
- **Kahle, oft nicht juckende Stellen**, besonders im Gesicht
- Häufig bei Welpen oder immungeschwächten Hunden
- Kann sich generalisieren und ernst werden

### Cheyletiellen
Auch „Laufende Schuppen" genannt — die Milben selbst sind manchmal im Fell beweglich sichtbar. Zeichen:
- **Starke Schuppenbildung**
- Milder bis moderater Juckreiz
- Auf Menschen übertragbar (Juckreiz beim Halter!)

### Haarlinge und Läuse
Selten, aber möglich. Zeichen ähnlich wie Flöhe — Eier (Nissen) sind an Haaren festgekittet.

## Wie du selbst prüfen kannst

- **Flohkot-Test**: Weißes Küchenpapier anfeuchten, Krümel aus dem Fell legen — Rötlich = Flohkot
- **Fell mit Kamm abkämmen** auf weißem Untergrund — sichtbare Parasiten?
- **Ohren kontrollieren**: Brauner, krümeliger Belag kann auf Ohrenmilben hindeuten

Für Milben-Diagnose: Hautgeschabsel beim Tierarzt ist der Goldstandard.

## Häufige Fragen

### Was mache ich, wenn ich Flöhe finde?
Den Hund behandeln, aber auch die **Umgebung** — 95 % der Flöhe leben nicht auf dem Hund, sondern in der Wohnung. Bettzeug, Teppiche, Polstermöbel müssen ebenfalls behandelt werden.

### Kann mein Hund Milben bekommen, obwohl er nie Kontakt zu anderen Hunden hatte?
Ja, Demodex-Milben sind ohnehin immer vorhanden. Sarcoptes kann auch indirekt übertragen werden.

### Welche Mittel gegen Flöhe sind sicher?
Nur vom Tierarzt empfohlene Präparate verwenden. Keine Produkte aus dem Drogeriemarkt mit fraglichen Wirkstoffen.

## Das Wichtigste in Kürze

- Parasiten immer als erstes ausschließen — vor Allergie- oder Ernährungsdiagnose
- Flohkot-Test zu Hause leicht durchführbar
- Milben brauchen tierärztliche Diagnostik (Hautgeschabsel)
- Bei Flohbefall auch die Wohnungsumgebung behandeln`,
