    tags: ["floehe", "diagnose", "parasiten", "fell"],
    imageUrl: "/images/tipps/fell-haut/3.jpg",
    imageAlt: "Nahaufnahme von Flohkot auf einem weißen Papiertuch mit rötlicher Verfärbung",
    content: `Der Flohkot-Test ist einer der einfachsten und verlässlichsten Selbsttests, die du für deinen Hund machen kannst. In zwei Minuten weißt du, ob dein Hund Flöhe hat — auch wenn du keinen einzigen Floh gesehen hast.

## Warum Flöhe schwer direkt zu sehen sind

Flöhe sind klein, schnell und meiden Licht. Sie springen weg, bevor du sie siehst. Zudem verbringen Flöhe nur einen kleinen Teil ihrer Zeit auf dem Wirt — der Rest ihrer Lebenszeit spielt sich in der Umgebung ab. Ein Hund mit Flöhen muss deshalb nicht voller sichtbarer Flöhe sein.

Der Kot der Flöhe hingegen bleibt im Fell hängen und verrät den Befall.

## Der Test: Schritt für Schritt

**Du brauchst:**
- Weißes Küchenpapier oder ein weißes Tuch
- Wasser oder einen feuchten Tupfer

**Durchführung:**
1. Kämme deinen Hund über dem weißen Papier aus oder drücke das Fell über dem Papier aus
2. Schaue, ob schwarze oder dunkelbraune Krümel fallen
3. Feuchte das Papier leicht an
4. Warte 30 Sekunden

**Ergebnis:**
- **Krümel werden rötlich-braun**: Das ist verdautes Blut — eindeutiger Flohkot, also Flohbefall
- **Krümel bleiben schwarz oder braun und werden nicht rötlich**: Wahrscheinlich normaler Schmutz

## Wo du suchen solltest

Flohkot sammelt sich besonders an Stellen, wo der Hund liegt oder sich oft putzt:
- Rücken nahe der Rute
- Bauch und Leiste
- Hals- und Nackenbereich
- Am Kissen oder der Schlafdecke des Hundes

## Was tun bei positivem Befund?

1. **Den Hund behandeln** — mit einem vom Tierarzt empfohlenen Flohpräparat
2. **Die Umgebung behandeln** — Flöhe legen Eier in der Wohnung; Decken, Teppiche, Polstermöbel und Ritzen müssen behandelt werden
3. **Alle Haustiere im Haushalt behandeln** — auch Katzen
4. **Regelmäßig kontrollieren** — Flohbehandlungen brauchen manchmal mehrere Zyklen

## Häufige Fragen

### Mein Hund kratzt sich, aber der Test ist negativ — trotzdem Flöhe?
Möglich, aber unwahrscheinlich bei intensivem Befall. Führe den Test mehrmals durch und schaue auch im Schlafbereich. Andere Ursachen für Juckreiz gleichzeitig prüfen.

### Wie schnell wirken Flohpräparate?
Je nach Wirkstoff innerhalb von Stunden bis 24 Stunden. Die Umgebungsbehandlung ist langwieriger — Flohpuppen im Teppich können das Präparat nicht erreichen und erst nach Wochen schlüpfen.

### Kann mein Hund eine Allergie auf Flohspeichel haben?
Ja, das ist die sogenannte Flohspeichelallergie (FAD — Flea Allergy Dermatitis). Bei diesen Hunden kann ein einziger Flohbiss starken Juckreiz auslösen — besonders am Rücken nahe der Rute.

## Das Wichtigste in Kürze

- Der Flohkot-Test auf feuchtem weißen Papier ist einfach und verlässlich
- Rötliche Verfärbung = Flohkot = Flohbefall
- Hund und Umgebung müssen gleichzeitig behandelt werden
- Alle Haustiere im Haushalt einbeziehen`,
