    imageUrl: "/images/tipps/fell-haut/4.jpg",
    imageAlt: "Tierarzt nimmt ein Hautgeschabsel von einem Hund zur Milbendiagnose",
    content: `Milben sind mit bloßem Auge unsichtbar — aber ihre Auswirkungen auf den Hund sind sehr spürbar. Heftigster Juckreiz, Krusten, Haarverlust: Milben sind nicht zu unterschätzen und brauchen immer eine spezifische Behandlung.

## Welche Milben kommen beim Hund vor?

### Sarcoptes scabiei (Räudemilben)
- Graben sich in die Haut ein und legen dort Eier
- Verursachen **extremen, oft nächtlichen Juckreiz**
- Befallen bevorzugt dünne Hautstellen: Ohrenränder, Ellbogen, Bauch, Pfoten
- **Hochansteckend** — auf andere Hunde und Menschen übertragbar
- Diagnose: Hautgeschabsel (Milben werden nicht immer gefunden, aber der Befund ist oft trotzdem eindeutig)

### Demodex canis (Haarbalgmilben)
- Leben normalerweise auf gesunder Hundehaut
- Vermehren sich bei Immunschwäche oder genetisch bedingter Anfälligkeit massenhaft
- Verursachen **Haarverlust, oft ohne Juckreiz**
- Bei Welpen häufig lokale Demodikose (gut behandelbar), bei erwachsenen Hunden kann sie generalisieren
- Diagnose: Hautgeschabsel, Biopsie bei tiefer Form

### Cheyletiella yasguri (Pelzmilben)
- Auslöser der „laufenden Schuppen"
- Starke Schuppenbildung, milder bis moderater Juckreiz
- Auf Menschen übertragbar (Juckreiz beim Halter)
- Leichter nachzuweisen als Sarcoptes

### Otodectes cynotis (Ohrenmilben)
- Leben im Gehörgang
- Zeichen: Dunkler, krümeliger Belag im Ohr, starkes Kopfschütteln, Kratzen am Ohr
- Sehr ansteckend zwischen Hunden und Katzen

## Die Diagnose

Für Milben gibt es keine verlässliche Methode zu Hause. **Das Hautgeschabsel** (auch Skin-Scraping genannt) ist der Goldstandard: Der Tierarzt kratzt oberflächlich oder tief Haut ab und untersucht sie unter dem Mikroskop.

**Wichtig:** Bei Sarcoptes werden die Milben oft nicht gefunden, obwohl sie vorhanden sind. Ein negativer Befund schließt Räude nicht sicher aus. Die Reaktion auf eine Behandlung kann dann als diagnostisches Kriterium dienen.

## Zeichen, die auf Milben hindeuten

- Juckreiz, der auf normale Floh- oder Allergie-Behandlung **nicht reagiert**
- Befall besonders an Ohrenrändern und Ellbogen (Sarcoptes typisch)
- Juckreiz beim Halter (verdächtig für ansteckende Arten)
- Kahlstellen ohne Juckreiz bei Welpen (Demodex)

## Häufige Fragen

### Sind Milbenmittel aus der Drogerie wirksam?
Meist nicht ausreichend. Milbenbehandlung braucht spezifische Wirkstoffe (Ivermectin, Milbemycin, Selamectin u.a.) nach tierärztlicher Verordnung.

### Muss ich mich bei Räude auch behandeln?
Bei Sarcoptes kann der Mensch vorübergehend Juckreiz bekommen. Die Milben vermehren sich beim Menschen nicht langfristig, aber ein Arztbesuch ist sinnvoll.

### Wie lange dauert die Behandlung?
Je nach Milbenart und Präparat mehrere Wochen. Alle Kontakttiere müssen oft mitbehandelt werden.

## Das Wichtigste in Kürze

- Milben sind unsichtbar, aber ihre Symptome sind eindeutig
- Sarcoptes: heftiger Juckreiz, ansteckend; Demodex: Haarverlust, wenig Juckreiz
- Hautgeschabsel beim Tierarzt ist die wichtigste Diagnosemethode
- Milbenbehandlung braucht spezifische Wirkstoffe — nicht selbst behandeln`,
