    level: 2,
    tags: ["pilz", "haut", "ringelflechte", "diagnose"],
    imageUrl: "/images/tipps/fell-haut/5.jpg",
    imageAlt: "Kreisrunde kahle Stelle im Fell eines Hundes — typisches Zeichen für Hautpilz",
    content: `Eine kreisrunde, schuppige Kahlstelle — das Bild, das die meisten Hundehalter mit Hautpilz verbinden. Aber Pilzinfektionen beim Hund sind vielfältiger als das klassische Bild. Und weil sie auf Menschen übertragbar sind, ist schnelles Handeln sinnvoll.

## Was ist Dermatophytose (Ringelflechte)?

Die Ringelflechte wird nicht durch einen Wurm verursacht — trotz des englischen Namens „Ringworm". Es handelt sich um eine Pilzinfektion durch Dermatophyten, vor allem Microsporum canis. Diese Pilze befallen die Haarwurzel und den äußeren Bereich der Haut.

**Übertragung:** Durch direkten Kontakt mit infizierten Tieren oder deren Schuppen und Haaren. Pilzsporen können monatelang in der Umgebung überleben.

## Typische Zeichen beim Hund

- **Kreisrunde, begrenzte Kahlstellen**, oft mit schuppiger, leicht geröteter Haut in der Mitte
- **Wenig oder kein Juckreiz** — das unterscheidet den Pilz von vielen Milbeninfektionen
- Stellen können langsam wachsen oder sich ausbreiten
- Häufig am **Kopf, Pfoten oder Rumpf**
- Bei immungeschwächten Hunden kann der Befund großflächiger sein

**Achtung:** Nicht jede Kahlstelle ist ein Pilz — Demodex, Allergien und Bakterieninfektionen können ähnlich aussehen.

## Übertragbarkeit auf Menschen

Ringelflechte geht auf Menschen über. Die Infektion beim Menschen zeigt sich als rote, ringförmige, juckende Stelle auf der Haut. Besonders gefährdet sind Kinder, ältere Menschen und Personen mit geschwächtem Immunsystem.

**Bei Verdacht:**
- Wenig direkten Körperkontakt mit dem Hund
- Hände nach Berührung gründlich waschen
- Keine gemeinsamen Handtücher oder Bettwäsche

## Diagnose und Behandlung

Der Tierarzt kann:
- **Wood-Lampe** nutzen (manche Pilze leuchten grün) — aber nicht alle Pilze reagieren darauf
- **Pilzkultur** anlegen (zuverlässigste Methode, dauert aber Tage bis Wochen)
- **Mikroskopische Haaruntersuchung** durchführen

Die Behandlung erfolgt topisch (Shampoos, Cremes) und manchmal oral mit Antimykotika. **Auch die Umgebung** muss gereinigt und desinfiziert werden, da Sporen lange überleben.

## Häufige Fragen

### Wird Ringelflechte von selbst besser?
Bei gesunden, erwachsenen Hunden manchmal — aber das dauert Monate und gefährdet Menschen im Haushalt. Behandeln ist sicherer und schneller.

### Muss mein Hund in Quarantäne?
Strikte Isolation ist selten nötig, aber Kontakt zu anderen Tieren und empfindlichen Personen sollte reduziert werden bis zur Behandlung.

### Welche Hygienemaßnahmen sind wichtig?
Schlafplätze, Bürsten und Decken desinfizieren. Regelmäßiges Staubsaugen mit Entsorgung des Sacks. Hände nach Hundekontakt waschen.

## Das Wichtigste in Kürze

- Kreisrunde, schuppige Kahlstellen ohne Juckreiz — typisch für Ringelflechte
- Auf Menschen übertragbar — Hygienemaßnahmen sofort einleiten
- Pilzkultur durch den Tierarzt ist die zuverlässigste Diagnose
- Behandlung immer konsequent durchführen und Umgebung desinfizieren`,
