    title: "Hot Spots beim Hund schnell behandeln: Was zu tun ist",
    shortDescription:
      "Nässende, entzündete Hautstellen entstehen rasch durch Lecken. Sie brauchen Reinigung, Behandlung und Schutz vor weiterem Lecken.",
    level: 2,
    tags: ["hotspot", "haut", "entzuendung", "behandlung"],
    imageUrl: "/images/tipps/fell-haut/6.jpg",
    imageAlt: "Nässende Hautentzündung am Körper eines Hundes — ein Hot Spot",
    content: `Hot Spots entstehen scheinbar über Nacht. Morgens ist alles gut, abends hat dein Hund eine feuchte, rötliche, kahle Hautstelle, die er nicht in Ruhe lässt. Sie sind schmerzhaft, sehen schlimm aus — und müssen rasch behandelt werden.

## Was ist ein Hot Spot?

Der medizinische Begriff ist „akute feuchte Dermatitis" oder „Pyotraumatische Dermatitis". Er entsteht in einem schnellen Kreislauf:

1. Ein **Auslöser** schafft Juckreiz oder Irritation (Floh, Allergie, Wunde, Fremdkörper)
2. Der Hund **leckt, kratzt oder beißt** an der Stelle
3. Die Haut wird verletzt und **bakteriell infiziert**
4. Die Entzündung macht die Stelle noch juckender
5. Der Hund leckt noch mehr — der Kreislauf eskaliert

Hot Spots breiten sich innerhalb von Stunden deutlich aus, wenn der Hund nicht daran gehindert wird.

## Typische Zeichen

- Nässende, rote, heiße Stelle auf der Haut
- Fell in der Umgebung oft feucht oder verklebt
- Der Hund leckt oder kratzt intensiv daran
- Mögliche Krusten oder Eiter
- Oft unangenehmer Geruch

Typische Stellen: Hals, Oberschenkel, hinter den Ohren, Wangen.

## Was du sofort tun kannst

### Schritt 1: Fell entfernen
Das Fell um den Hot Spot muss freigeschnitten oder geschoren werden. Nasses Fell über der entzündeten Stelle hält die Feuchtigkeit — eine trockene, freie Wunde heilt besser. Das am besten mit kleinen Scheren oder vom Tierarzt.

### Schritt 2: Reinigen
Die Wunde mit einer milden, antiseptischen Lösung oder Kochsalzlösung reinigen. Keine Produkte mit Alkohol — das schmerzt und trocknet die Haut zu stark aus.

### Schritt 3: Lecken verhindern
Das ist entscheidend. Schutzkragen (Elizabethkragen) oder ein Schutz-Body verhindern weiteres Lecken. Ohne diesen Schritt ist jede Behandlung wirkungslos.

### Schritt 4: Tierarzt kontaktieren
Ein größerer oder sich ausbreitender Hot Spot braucht tierärztliche Behandlung — oft mit antibiotischer Salbe oder oralen Antibiotika. Der Auslöser muss ebenfalls gefunden und behandelt werden.

## Häufige Auslöser

- Flohbefall oder Flohspeichelallergie
- Allergien (Futter oder Umwelt)
- Eingewachsene Grannen oder Fremdkörper im Fell
- Feuchtigkeit nach dem Schwimmen oder Regen
- Stress und Langeweile (zwanghaftes Lecken)

## Häufige Fragen

### Kann ich einen Hot Spot selbst behandeln?
Kleine, frische Hot Spots können mit Reinigen und Schutzkragen anbehandelt werden. Bei großen, eitrigen oder schnell wachsenden Stellen zum Tierarzt.

### Wie schnell heilen Hot Spots?
Bei konsequenter Behandlung und ohne weiteres Lecken oft innerhalb von 7–14 Tagen. Ohne Schutz: gar nicht.

### Mein Hund bekommt immer wieder Hot Spots — warum?
Ein wiederkehrender Hot Spot deutet auf einen unbehandelten Auslöser hin — am häufigsten eine unbehandelte Allergie oder Parasitenproblematik.

## Das Wichtigste in Kürze

- Hot Spots entstehen schnell durch lecken-entzünden-lecken-Kreislauf
- Fell freischneiden, reinigen und das Lecken sofort unterbinden
- Tierarzt bei großen, eitrigen oder sich ausbreitenden Stellen
- Den Auslöser finden und behandeln, um Rezidive zu verhindern`,
    seoTitle: "Hot Spots beim Hund behandeln: Sofortmaßnahmen und Ursachen",
