    shortDescription:
      "Grannen, Zecken und Schmutz sammeln sich im Fell. Kontrolliere besonders Pfoten, Achseln, Ohren und Bauch.",
    level: 0,
    tags: ["kontrolle", "pflege", "grannen", "zecken"],
    imageUrl: "/images/tipps/fell-haut/7.jpg",
    imageAlt: "Hundebesitzer kontrolliert die Pfoten seines Hundes nach einem Spaziergang im Wald",
    content: `Die Runde ist schön gewesen, der Hund ist glücklich — aber bevor du nach Hause kommst, lohnt ein kurzer, systematischer Check. Was sich im Fell versteckt, kann von harmlosem Schmutz bis zu medizinisch relevanten Problemen reichen.

## Was sich beim Spaziergang im Fell sammelt

### Zecken
Die klassische Gefahr im Grünbereich. Zecken suchen warme, behaarte Stellen auf dem Körper und haken sich fest. Je früher du sie entfernst, desto geringer das Übertragungsrisiko von Krankheitserregern.

**Typische Stellen:** Hinter den Ohren, Achseln, Leiste, zwischen den Zehen, um Augen und Lefzen.

### Grannen
Pflanzenartige Stacheln von Wildgräsern (besonders Getreide und Raygras), die durch ihre Form wie ein Widerhaken ins Fell eindringen und sich einbohren. In der Haut, in Ohren oder zwischen den Zehen können sie starke Entzündungen verursachen.

**Hochsaison:** Spätsommer bis Herbst, besonders auf Feldwegen und Wiesen.

### Schmutz, Harz, Samen
Das meiste ist harmlos und lässt sich ausbürsten. Harz ist klebrig und härtet aus — frisch ist es einfacher zu entfernen.

### Insektenstiche
Bienenstecher, Wespen und Mücken können sich im Fell versteckt haben. Schwellungen, vor allem im Gesicht, immer beachten.

## Der systematische Körper-Check

Kurzer, fester Ablauf nach dem Spaziergang:

1. **Pfoten**: Zwischen jedem Zeh kontrollieren, Ballen abtasten
2. **Achseln**: Häufige Zeckenstelle
3. **Ohren**: Außen und innen in die Muschel schauen (nicht stochern)
4. **Bauch und Leiste**: Dünne Haut, Zecken hängen hier gerne
5. **Hintere Beine**: Hosen und Schenkel
6. **Rute** und Ansatz
7. **Kopf**: Hinter den Ohren, um die Augen, an den Lefzen

Das dauert bei Übung zwei bis drei Minuten.

## Wie du Grannen findest

Grannen sind schwer zu sehen, aber du kannst sie ertasten:
- Das Fell in kleinen Abschnitten gegen den Strich streichen
- Kleine, harte, spitz zulaufende Partikel tasten
- Besonders zwischen den Zehen sorgfältig suchen

**Warnsignal:** Wenn dein Hund plötzlich eine Pfote hochhält, schüttelt, leckt oder hinkt — sofort auf Grannen prüfen.

## Häufige Fragen

### Muss ich nach jedem Spaziergang den ganzen Körper prüfen?
Im Sommer und in Zeckensaison: ja, zumindest die gefährdetsten Stellen. Im Winter reicht ein schneller Blick auf Pfoten und Bauch.

### Ich habe eine Granne gefunden — kann ich sie selbst entfernen?
Oberflächlich sitzende Grannen kannst du mit einer Pinzette entfernen. Grannen im Ohr oder tief in der Haut: Tierarzt.

### Wie vermeide ich Grannen?
Bekannte Grannenstellen meiden oder nach dem Spaziergang besonders sorgfältig prüfen. In Hochrisikogebieten: Fell kurz halten.

## Das Wichtigste in Kürze

- Nach jedem Spaziergang einen schnellen, systematischen Check machen
- Pfoten, Achseln, Ohren, Bauch und Leiste sind die wichtigsten Stellen
- Zecken sofort entfernen, Grannen frühzeitig finden
- Bei verdächtigen Symptomen wie Hinken oder Schütteln sofort handeln`,
