    shortDescription:
      "Bei langhaarigen Rassen das Fell zwischen den Ballen kürzen. Es verfilzt, sammelt Schmutz und kann das Laufen behindern.",
    level: 1,
    tags: ["pfoten", "pflege", "ballen", "fell"],
    imageUrl: "/images/tipps/fell-haut/9.jpg",
    imageAlt: "Pfote eines langhaarigen Hundes mit gekürztem Fell zwischen den Ballen",
    content: `Pfoten sind das Fundament deines Hundes — sie tragen ihn durch jedes Gelände. Aber gerade bei langhaarigen Rassen wird das Fell zwischen den Ballen oft vergessen, bis es zum Problem wird.

## Warum Ballenfell Aufmerksamkeit braucht

Zwischen den Ballen wächst bei vielen Hunden langes, feines Fell. Das klingt unproblematisch, kann aber folgende Schwierigkeiten verursachen:

- **Verfilzung und Knotenbildung**: Das Fell zwischen den Zehen filzt schnell, besonders wenn es nass wird
- **Schmutzspeicher**: Erde, Sand, Splitt, Streusalz und Grannen hängen sich ins lange Fell
- **Rutschgefahr**: Langes Ballenfell auf glattem Boden reduziert den Grip erheblich
- **Pflanzensamen und Grannen**: Dringen leicht in langes Fell ein und bohren sich zur Haut durch
- **Feuchtes Milieu**: Langes Fell hält Nässe fest, was Pododermatitis (Entzündung der Pfote) begünstigt

## Wie oft und wie kürzen?

Für langhaarige und mittellanghaarige Hunde: Das Fell sollte die Ballenhöhe nicht deutlich überragen. Als Faustregel: **Das Fell zwischen den Ballen sollte bündig mit den Ballen abschließen** — nicht darunter hervorstehen.

**Häufigkeit:** Je nach Wuchsrate alle zwei bis vier Wochen überprüfen und bei Bedarf kürzen.

**Werkzeug:**
- Kleine, gebogene Nagelschere oder Schermaschine mit kurzer Scherkopflänge
- Schere an der Seite des Ballens entlangführen, nicht quer
- Immer mit Licht prüfen — zwischen den Zehen ist es schnell dunkel

## Wie du es sicher machst

1. Hund ruhig halten oder hinlegen lassen
2. Pfote vorsichtig aufnehmen und einzelne Zehen auseinanderspreizen
3. Fell vorsichtig kürzen — nie zu nah an der Haut, lieber konservativ
4. Die Ballen dabei gleichzeitig auf Risse, Rötungen oder Fremdkörper prüfen

## Ballen-Pflege: Was noch wichtig ist

- **Ballenbalsam**: Bei trockenen, rissigen Ballen regelmäßig auftragen — besonders im Winter und bei starker Hitze
- **Streusalz**: Nach Winterspaziergängen die Pfoten abspülen
- **Risse**: Tiefe Risse können sehr schmerzhaft sein — bei stark rissigen Ballen tierärztlichen Rat einholen

## Häufige Fragen

### Mein Hund lässt keine Pfotenpflege zu — was tun?
Aufbauen mit Geduld: Pfoten berühren, belohnen, immer kürzer werden. Viele Hunde lernen es mit positiver Verstärkung. Bei starker Abwehr: Tierarzt oder erfahrener Hundefriseur.

### Kann ich die Krallen gleichzeitig kürzen?
Ja, wenn du weißt wie. Krallen kürzen braucht das richtige Werkzeug (Krallenschneider) und Kenntnis des „Quick" (Blutgefäß in der Kralle). Bei Unsicherheit: Tierarzt oder Hundefriseur.

### Was ist, wenn zwischen den Ballen eine Rötung ist?
Pododermatitis — eine Entzündung der Interdigitalhaut. Die Ursache prüfen (Allergie, Fremdkörper, Pilz) und bei Fortdauer tierärztlich abklären.

## Das Wichtigste in Kürze

- Fell zwischen den Ballen regelmäßig auf Ballenhöhe kürzen
- Verhindert Verfilzungen, Rutschgefahr und Granneneinwanderung
- Ballen gleichzeitig auf Risse und Entzündungen prüfen
- Ballenbalsam bei trockener oder gerissener Haut`,
