      "Warum Rauhaarhunde getrimmt und nicht geschoren werden sollten. Alles über Handtrimmen, Häufigkeit und wie Scheren das Fell dauerhaft schädigt.",
    keywords: ["hund rauhaar trimmen", "drahthaar hund scheren falsch", "westie trimmen", "dackel rauhaar pflege", "handtrimmen hund", "terrier trimmen anleitung"],
