      "Bei Doppelhaarrassen staut sich abgestorbene Unterwolle. Ein Unterwollkamm holt sie heraus und beugt Hitzestau und Hautproblemen vor.",
    level: 1,
    tags: ["unterwolle", "buersten"],
    imageUrl: "/images/tipps/fell-haut/12.jpg",
    imageAlt: "Großer Berg loser Unterwolle neben einem gepflegten Hund",
    content: `Nach einer Bürstsitzung mit einem Huskymix liegen manchmal Hunderte Gramm Unterwolle auf dem Boden — und der Hund wirkt, als hätte er kaum weniger Fell. **Die Unterwolle macht das aus.** Dicht, weich und unsichtbar unter dem Deckhaar staut sie sich im Fellwechsel. Wer sie nicht regelmäßig entfernt, schafft ideale Bedingungen für Hitzestau und Hautentzündungen.

## Was ist Unterwolle und warum entsteht sie?

Die Unterwolle ist die innere, weiche, wärmende Schicht des Fells bei Doppelhaarrassen. Im Fellwechsel stirbt sie ab, löst sich aber nicht wie das Deckhaar einfach heraus. Stattdessen bleibt sie im Fell hängen und bildet dichte Matten zwischen Deckhaar und Haut.

Rassen mit ausgeprägter Unterwolle:
- Husky, Malamute, Samojede
- Deutscher Schäferhund, Belgischer Schäferhund
- Berner Sennenhund, Eurasier
- Golden Retriever, Labrador (weniger, aber vorhanden)
- Corgi, Chow Chow

## Folgen von zu viel Unterwolle

- **Hitzestau:** Die Unterwolle isoliert — gut im Winter, problematisch im Sommer wenn sie sich abgestorbene Wolle staut
- **Feuchtigkeitsstau:** Nasse Unterwolle trocknet kaum, begünstigt Hautentzündungen und Hot Spots
- **Verfilzung:** Abgestorbene Unterwolle verfilzt und bildet Matten auf der Haut
- **Juckreiz:** Durch Hitzestau und Feuchtigkeit

## Die richtigen Werkzeuge

### Unterwollkamm / Furminator-Typ
Diese Bürsten haben engzahlige Metallzähne, die durch das Deckhaar greifen und die Unterwolle herausziehen. Sehr effektiv — aber mit Maß einsetzen: zu aggressives Bürsten kann das Deckhaar beschädigen.

### Unterwollrake / Slicker Brush
Breite, leicht gebogene Zähne — gut zum Lösen von geklumpter Unterwolle, bevor der Furminator kommt.

### Profi-Unterwollbad
Beim Friseur: warmes Wasser löst die abgestorbene Unterwolle sehr effektiv. Nach dem Trocknen (mit Hochgeschwindigkeitsföhn) bleibt oft das Vielfache an normaler Bürstmenge zurück.

## Wie du die Unterwolle gründlich entfernst

1. **Beginn mit dem Slicker** oder einer weichen Bürste, um grobe Verklumpungen zu lösen
2. **Unterwollkamm einsetzen** — mit gleichmäßigem Druck, nicht zu tief in Richtung Haut
3. **Abschnitt für Abschnitt** arbeiten — nicht wild über den ganzen Körper
4. **Gegen und mit dem Strich** — beides liefert Unterwolle
5. **Empfindliche Stellen zuletzt** — Achseln, Bauch, hinter den Ohren

## Häufigkeit

- Im Fellwechsel: täglich oder jeden zweiten Tag
- Außerhalb des Wechsels: wöchentlich bis zweiwöchentlich

## Häufige Fragen

### Kann ich den Hund scheren, damit ich keine Unterwolle ausbürsten muss?
Nein. Scheren zerstört die Funktion des Doppelfells und löst keine Unterwolle. Das Ausbürsten bleibt notwendig, und nach dem Scheren wächst das Fell unregelmäßig nach.

### Wann höre ich auf zu bürsten?
Wenn keine Unterwolle mehr kommt. Bei manchen Hunden hört man nach der fünften Runde noch auf. Das ist okay — den Rest macht der Körper.

## Das Wichtigste in Kürze

- Abgestorbene Unterwolle staut Hitze und Feuchtigkeit
- Unterwollkamm und Slicker Brush sind die richtigen Werkzeuge
- Im Fellwechsel täglich, sonst wöchentlich bürsten
- Professionelles Unterwollbad beim Friseur sehr effektiv`,
    seoTitle: "Unterwolle beim Hund entfernen: Werkzeuge, Technik und Häufigkeit | BELLA",
