    slug: "hautroetenungen-beobachten",
    title: "Hautrötungen beim Hund: Wann du genauer hinschauen solltest",
    shortDescription:
      "Gerötete, warme oder geschwollene Hautstellen weisen auf Entzündungen hin. Beobachte sie und lass sie bei Verschlechterung behandeln.",
    level: 1,
    tags: ["haut", "symptome"],
    imageUrl: "/images/tipps/fell-haut/13.jpg",
    imageAlt: "Tierarzt untersucht gerötete Hautpartie eines Hundes",
    content: `Eine gerötete Hautstelle beim Hund wird oft übersehen — das Fell verdeckt sie. Beim Bürsten oder Abtasten taucht plötzlich eine warme, rote, vielleicht geschwollene Stelle auf. **Rötung ist immer ein Zeichen, dass etwas nicht stimmt.** Die Frage ist: Wie ernst ist es?

## Was hinter Hautrötungen stecken kann

Hautrötungen entstehen, wenn der Körper mehr Blut in ein Gewebe schickt — als Reaktion auf Reizung, Verletzung oder Entzündung. Mögliche Ursachen:

- **Kontaktreizung:** Reibung durch Geschirr, Halsband oder Liegeplatz
- **Parasiten:** Flöhe, Milben, Zecken hinterlassen gerötete Einstichstellen
- **Allergien:** Futter- oder Umweltallergien zeigen sich oft als Rötungen an Bauch, Pfoten und Ohren
- **Pilzinfektionen:** z.B. Malassezia oder Hautpilz
- **Bakterielle Infektionen:** oft als nässende Rötung mit Kruste
- **Hot Spots:** Entzündete, nässende Hautstellen durch Lecken
- **Sonnenbrand:** Besonders an Nase, Ohren und Bauch bei heller Haut

## Was du beim Bürsten notieren solltest

Wenn du eine gerötete Stelle findest, achte auf:

- **Wie groß** ist sie? (kleiner roter Punkt vs. flächige Rötung)
- **Ist die Haut warm** dort?
- **Riecht es** aus dem Bereich?
- **Schuppt oder näss**t die Stelle?
- **Kratzt, leckt oder beißt** der Hund die Stelle?
- **War da zuletzt ein Insektenstich** oder Reibestelle?

Diese Informationen helfen dem Tierarzt enorm.

## Abwarten oder sofort zum Tierarzt?

**Abwarten und beobachten (1–3 Tage):**
- Kleine, isolierte rote Stelle ohne nässende Wunde
- Keine Reaktion des Hundes
- Kein Geruch

**Sofort zum Tierarzt:**
- Schnell wachsende oder großflächige Rötung
- Nässende oder eitrige Wunde
- Starker Juckreiz — Hund kratzt/leckt ständig
- Hund wirkt schmerzhaft beim Berühren
- Fieber, Apathie oder andere Allgemeinsymptome

## Was du nicht tun solltest

- Menschliche Kortisoncremes oder Antibiotika-Salben ohne Verschreibung auftragen
- Die Stelle aufkratzen oder reinigen mit Alkohol (brennt und schädigt die Haut)
- Abwarten, wenn sich die Stelle schnell verschlechtert

## Häufige Fragen

### Mein Hund hat rote Stellen zwischen den Zehen — was ist das?
Rötungen zwischen den Zehenzwischenräumen sind sehr häufig und können auf Allergien, Kontaktreizung oder Hefepilz hindeuten. Beim Tierarzt abklären lassen.

### Ist Rötung nach dem Bürsten normal?
Leichte Reizrötung direkt nach dem Bürsten auf empfindlicher Haut kann normal sein. Wenn sie anhält oder stark ist: Bürste zu hart, Druck zu stark.

## Das Wichtigste in Kürze

- Hautrötungen sind immer ein Zeichen für Reizung oder Entzündung
- Größe, Wärme, Geruch, nässende Wunde und Schmerzreaktion notieren
- Kleine isolierte Stellen: beobachten
- Wachsend, nässend, stark juckend, mit Schmerz: sofort tierärztlich`,
