    id: 52,
    slug: "geruch-hund-indikator",
    title: "Fellgeruch beim Hund: Was strenger Eigengeruch verrät",
    shortDescription:
      "Ein plötzlich strenger Fellgeruch kann auf Haut- oder Ohrprobleme hindeuten. Übermäßiger Eigengeruch ist nicht normal.",
    level: 1,
    tags: ["geruch", "symptome"],
    imageUrl: "/images/tipps/fell-haut/14.jpg",
    imageAlt: "Hund liegt auf dem Sofa, Besitzer rümpft leicht die Nase",
    content: `Hunde riechen nach Hund — das ist normal. Aber es gibt Gerüche, die über den natürlichen Eigengeruch hinausgehen: **ein plötzlich auftretender, strenger, fauliger oder süßlicher Geruch ist ein diagnostisches Signal.** Bevor du zum Shampoo greifst, lohnt es sich zu verstehen, woher er kommt.

## Was normaler Hundegeruch ist

Hunde schwitzen kaum über die Haut. Ihr natürlicher Geruch kommt hauptsächlich aus:

- Talgdrüsen in der Haut (ein leicht muffiger, warmer „Hundeduft")
- Apokrine Drüsen an Pfoten und in der Leiste
- Natürlich vorhandenen Bakterien auf der Haut

Dieser Grundgeruch ist für jede Nase erkennbar und leicht vorhanden. Wenn er sich plötzlich ändert oder verstärkt, ist das ein Hinweis.

## Typische Gerüche und ihre Ursachen

### Fischiger Geruch
Oft: **volle Analdrüsen**. Der Hund „fährt Schlitten" oder leckt am Po. Analdrüsenentleerung beim Tierarzt oder Friseur nötig.

### Süßlich-fermentierter Geruch
Oft: **Hefepilzinfektionen** (Malassezia). Typischerweise im Ohr, zwischen Pfotenzehen oder in Hautfalten. Begleitend oft Juckreiz und Rötung.

### Eitriger oder fauliger Geruch
Mögliche bakterielle Infektionen, Wunden, Abszesse oder **Zahnprobleme**. Zahnfleischerkrankungen können das ganze Maul und das angrenzende Fell betreffen.

### Strenger, muffiger Geruch nach dem Spaziergang
Oft nur: der Hund hat sich gewälzt oder Kontakt mit etwas hatte. Aber auch übermäßig fettiges Fell oder Seborrhö.

### Ohrgeruch
Stark riechende Ohren deuten auf **Ohrentzündung** hin — häufig durch Bakterien, Hefepilze oder Milben. Ohr ansehen und beim Tierarzt vorstellen.

## Warum Geruch überdecken keine Lösung ist

Duftendes Hundeshampoo, Hundeparfüm oder stark duftende Pflegeprodukte überdecken Geruch — lösen aber keine Ursache. Wenn ein Hund trotz häufigen Waschens schnell wieder stark riecht, ist die Ursache im Körper, nicht im Fell.

## Wann zum Tierarzt?

- Geruch tritt plötzlich auf ohne äußerlichen Grund
- Hund zeigt zusätzlich Juckreiz, Rötung oder Apathie
- Geruch kommt aus Ohren, Mund oder Analbereich
- Badenergebnis hält weniger als 24 Stunden

## Häufige Fragen

### Wie oft soll ich meinen Hund waschen, wenn er stark riecht?
Übermäßig häufiges Baden verstärkt den Kreislauf oft. Die Haut produziert als Reaktion mehr Talg. Ursache klären statt häufiger waschen.

### Mein Hund riecht gut nach dem Bad, aber sofort wieder schlecht — warum?
Das deutet auf Seborrhö, Hefepilz oder starke Talgproduktion hin. Tierärztliche Abklärung.

## Das Wichtigste in Kürze

- Natürlicher Hundegeruch ist normal — plötzliche Veränderung ist ein Signal
- Fischig: Analdrüsen; süßlich: Hefepilz; faulig: Infektion oder Zähne
- Geruch überdecken ist keine Lösung
- Anhaltender starker Geruch trotz Sauberkeit: tierärztlich abklären`,
