    imageUrl: "/images/tipps/fell-haut/15.jpg",
    imageAlt: "Hundehalter schaut in das Ohr seines Hundes während der Pflegeroutine",
    content: `Die Ohren des Hundes werden bei der Fellpflege oft ausgelassen — dabei sind sie eine der häufigsten Problemzonen. **Ohrentzündungen gehören zu den häufigsten Erkrankungen beim Hund**, und viele davon ließen sich durch regelmäßige Kontrolle früh erkennen oder sogar vorbeugen.

## Warum Ohren besonders pflegebedürftig sind

Der Gehörgang des Hundes verläuft anders als beim Menschen: Er hat einen langen vertikalen Teil und dann einen horizontalen Abschnitt — eine L-Form. Das macht ihn anfälliger für Feuchtigkeit und Luftstau.

Zusätzliche Risikofaktoren:

- **Hängeohren** (Dackel, Spaniel, Bassett): Die Ohrmuschel bedeckt den Eingang, Luft zirkuliert kaum
- **Beharung im Gehörgang** (Pudel, Malteser, Havaneser): Haare blockieren den Selbstreinigungseffekt
- **Feuchtes Klima oder Schwimmen**: Wasser bleibt im Kanal — ideales Milieu für Bakterien und Hefe
- **Allergien**: Chronische Ohrentzündungen sind oft Zeichen einer Allergie

## Wie eine gesunde Ohrmuschel aussieht

- Helles, sauberes Inneres (leichte Wachsschicht ist normal)
- Kein unangenehmer Geruch
- Kein Ausfluss oder Krusten
- Hund kratzt nicht am Ohr

## Zeichen eines Problems

- Dunkler, brauner oder schwarzer Ausfluss → Hefe oder Milben
- Eitriger, gelblicher Ausfluss → Bakterien
- Starker Geruch aus dem Ohr → Entzündung
- Häufiges Kratzen am Ohr oder Kopfschütteln
- Ohrmuschel warm oder geschwollen
- Hund hält Kopf schief

## Wie du die Ohren in die Pflege integrierst

### 1. Regelmäßige Sichtkontrolle
Beim Bürsten einen kurzen Blick ins Ohr werfen. Nicht tief ins Ohr schauen — die oberflächliche Inspektion reicht für die tägliche Kontrolle.

### 2. Ohrmuschel reinigen (bei Bedarf)
Nur die sichtbare Ohrmuschel — nicht tief in den Kanal:
- Einen Wattebausch oder ein spezielles Ohrpflegetuch leicht mit Ohrreinigungslösung für Hunde befeuchten
- Sanft die sichtbare Innenseite wischen
- Nie mit Wattestäbchen tief in den Kanal gehen

### 3. Behaarung im Kanal
Manche Züchter und Friseure entfernen Haare im Gehörgang. Das Thema ist umstritten: Bei chronisch entzündungsanfälligen Hunden kann es helfen, bei gesunden Hunden ist es nicht notwendig. Tierärztlichen Rat einholen.

## Häufige Fragen

### Wie oft Ohren reinigen?
Bei gesunden Hunden mit normalen Ohren: einmal pro Woche kurz anschauen, bei Bedarf wischen. Häufiges aggressives Reinigen stört das natürliche Ohrklima.

### Mein Hund hat immer wieder Ohrentzündungen — was hilft?
Chronische Ohrentzündungen sind oft ein Symptom einer Grunderkrankung — meist Allergien. Die Ursache behandeln, nicht nur die Entzündung.

## Das Wichtigste in Kürze

- Ohren wöchentlich kurz kontrollieren beim Bürsten
- Nur Ohrmuschel reinigen, nie tief in den Kanal
- Dunkler Ausfluss, Geruch, Kratzen: tierärztlich abklären
- Chronische Ohrentzündungen auf Allergie-Ursache hin abklären lassen`,
