    id: 54,
    slug: "auf-schwellungen-reagieren",
    title: "Schwellungen beim Hund: Wann sofort zum Tierarzt?",
    shortDescription:
      "Plötzliche Schwellungen, etwa nach Insektenstichen, können gefährlich werden. Im Kopf- und Halsbereich sofort zum Tierarzt.",
    level: 1,
    tags: ["schwellung", "notfall"],
    imageUrl: "/images/tipps/fell-haut/16.jpg",
    imageAlt: "Hund mit geschwollenem Maul nach Insektenstich beim Tierarzt",
    content: `Eine plötzliche Schwellung beim Hund kann harmlos sein — oder ein medizinischer Notfall. **Im Kopf- und Halsbereich ist keine Zeit für Abwarten.** Hier musst du sofort handeln, weil eine Schwellung die Atemwege einengen kann.

## Wann ist eine Schwellung ein Notfall?

Sofort zum Tierarzt oder in eine Tierklinik, wenn:

- Die Schwellung im **Gesicht, am Hals, an Lippen oder Maul** auftritt
- Der Hund **Atemnot, Husten oder Würgen** zeigt
- Die Schwellung **innerhalb von Minuten** sichtbar zunimmt
- Der Hund **Schleimhäute** hat, die blass, bläulich oder sehr rot sind
- Der Hund **kollabiert** oder erschöpft wirkt

Diese Zeichen können auf einen **anaphylaktischen Schock** hinweisen — eine lebensbedrohliche allergische Reaktion, die innerhalb von Minuten lebensbedrohlich werden kann.

## Häufige Ursachen für Schwellungen

### Insektenstiche
Bienen, Wespen und Hornissen — besonders im Maul-/Schnauzenbereich bei neugierigen Hunden. Der Stich löst lokale Schwellung aus. Meist harmlos an Pfoten oder Körper. Gefährlich im Hals-/Rachenraum.

### Allergische Reaktion
Kontaktallergie, Futterallergie oder Reaktion auf ein Medikament. Angioödem (plötzlich geschwollene Augenlider, Lippen) ist ernst zu nehmen.

### Abszess
Eitrige Entzündung unter der Haut — warm, fest, schmerzhaft. Häufig nach Bisswunden oder Fremdkörpern. Braucht tierärztliche Behandlung.

### Hämatom
Blutansammlung nach Stoß oder Trauma. Weiche, fluktuierende Schwellung. Beim Ohr häufig (Ohrenhämatom nach heftigem Kopfschütteln).

### Tumor oder Zyste
Langsam wachsende Schwellung ohne Akutsymptome. Braucht Abklärung, aber kein Notfall.

## Was du sofort tun kannst

Bei Insektenstich an unkritischer Stelle (Pfote, Körper):

1. Den Stachel entfernen, falls vorhanden (bei Bienen)
2. Kühlen mit feuchtem Tuch (kein Eis direkt auf Haut)
3. Hund beobachten
4. Wenn Schwellung sich ausbreitet oder Hund unruhig wird: Tierarzt

Bei Stich im Maul oder Hals: **sofort in die Tierklinik**, auch wenn der Hund noch gut wirkt.

## Häufige Fragen

### Kann ich meinem Hund Antihistaminika aus der Menschenapotheke geben?
Nur nach ausdrücklicher Rücksprache mit dem Tierarzt. Manche Präparate sind für Hunde geeignet, andere nicht. Niemals eigenständig ohne Anweisung.

### Mein Hund hatte schon mal eine starke Reaktion — was tun?
Mit dem Tierarzt einen Notfallplan erstellen. In manchen Fällen wird ein Adrenalin-Pen für zuhause empfohlen.

### Ohrenhämatom — kann das von selbst heilen?
Kleine können sich zurückbilden, aber große Hämatome brauchen tierärztliche Behandlung um Verformung der Ohrmuschel zu verhindern.

## Das Wichtigste in Kürze

- Schwellung im Gesicht, Hals oder Maul = sofort Tierarzt
- Anaphylaktischer Schock: Atemnot, Kollaps, sich ausbreitende Schwellung = Notfall
- Insektenstich am Körper: kühlen und beobachten
- Abszess, Hämatom, Tumor: brauchen alle Abklärung, aber Dringlichkeit unterschiedlich`,
