    id: 56,
    slug: "hautpilz-hygiene-beachten",
    title: "Hautpilz beim Hund: Hygiene als Schlüssel zur Behandlung",
    shortDescription:
      "Hautpilz ist ansteckend. Reinige Liegeplätze, Bürsten und Decken gründlich und wasche dir nach dem Hantieren die Hände.",
    level: 2,
    tags: ["pilz", "hygiene"],
    imageUrl: "/images/tipps/fell-haut/18.jpg",
    imageAlt: "Desinfizierte Hundebürsten und gewaschene Hundeschlafdecke",
    content: `Hautpilz beim Hund ist mehr als ein Haustier-Problem — er ist ein **Zoonose**, also eine Erkrankung, die vom Tier auf den Menschen übertragen werden kann. Wer Hygienemaßnahmen vernachlässigt, riskiert, dass sich der Pilz im Haushalt ausbreitet. **Die Behandlung geht nur Hand in Hand mit konsequenter Reinigung.**

## Was ist Hautpilz beim Hund?

Hautpilz (Dermatophytose) wird meist durch den Pilz *Microsporum canis* verursacht. Er befällt Haare, Haut und Krallen. Typische Zeichen:

- Kreisrunde, schuppige, haarlose Stellen
- Rötung und leichte Schuppenbildung am Rand
- Wenig bis kein Juckreiz (im Unterschied zu Parasiten)
- Bevorzugte Stellen: Gesicht, Ohren, Pfoten, Schwanz

**Wichtig:** Hautpilz beim Hund muss durch einen Hautabstrich oder eine Pilzkultur bestätigt werden — er sieht anderen Hauterkrankungen ähnlich.

## Warum Hygiene so entscheidend ist

Pilzsporen sind extrem widerstandsfähig:

- Sie überleben **Monate bis Jahre** auf Oberflächen, Textilien und in Staub
- Sie werden durch **Haare, Schuppen und direkten Kontakt** übertragen
- Schimmel- oder Pilzsporen haftet an Bürsten, Decken, Kissen und im Teppich

Ohne parallele Dekontamination der Umgebung kommt es fast immer zu Rückfällen — selbst wenn der Hund behandelt wird.

## Maßnahmen im Haushalt

### Liegeplätze und Decken
- Alle Textilien, auf denen der Hund liegt, täglich oder mindestens dreimal pro Woche waschen
- Heiße Waschtemperatur (60 °C und höher) tötet Sporen ab
- Weiche Liegeplätze, die nicht waschbar sind, entfernen oder mit Pilzmittel einsprühen

### Bürsten und Kämme
- Nie dieselbe Bürste für kranken und gesunden Hund
- Bürsten täglich desinfizieren: kurzes Einlegen in verdünnte Bleichmittellösung oder spezielle Desinfektionsmittel
- Plastikbürsten sind leichter zu desinfizieren als Naturbürsten

### Böden und Oberflächen
- Täglich saugen (mit HEPA-Filter, damit Sporen nicht rausgepustet werden)
- Hartböden und Oberflächen mit einem pilzabtötenden Reiniger wischen

### Hände waschen
Nach jedem Kontakt mit dem kranken Hund — und nach der Umgebungsreinigung — gründlich Hände waschen. Bei erkrankten Kindern oder immungeschwächten Personen im Haushalt: tierärztlichen und humananärztlichen Rat einholen.

## Behandlung des Hundes

Die Behandlung des Hundes erfolgt durch den Tierarzt:
- Antifungale Shampoos (lokal)
- Orale Antimykotika (systemisch, bei schwerem Befall)
- Krallenpflege, wenn Krallen befallen sind

Behandlungsdauer: oft 6–12 Wochen, manchmal länger. Therapieabbruch bei scheinbarer Besserung führt zu Rückfall.

## Häufige Fragen

### Wie gefährlich ist Hautpilz für Menschen?
Kinder, Senioren und Menschen mit geschwächtem Immunsystem sind anfälliger. Es entstehen runde, juckende Ringe auf der Haut. Behandlung beim Arzt (Antimykotikum für Menschen).

### Muss ich den Hund isolieren?
In Mehrtierhaushalten ja: kranken Hund von gesunden Tieren trennen bis zur Ausbehandlung.

## Das Wichtigste in Kürze

- Hautpilz ist ansteckend — auf Menschen und andere Tiere
- Sporen überleben Monate auf Oberflächen und Textilien
- Täglich waschen, desinfizieren und saugen
- Behandlung durch Tierarzt — nie frühzeitig abbrechen`,
    seoTitle: "Hautpilz beim Hund: Hygiene, Behandlung und Ansteckungsgefahr | BELLA",
