    id: 57,
    slug: "pflegewerkzeuge-sauber-halten",
    title: "Hundebürsten sauber halten: Warum und wie du Pflege-Tools reinigst",
    shortDescription:
      "Bürsten und Kämme regelmäßig reinigen. Schmutzige Werkzeuge verteilen Keime und Parasiten im Fell.",
    level: 0,
    tags: ["hygiene", "ausruestung"],
    imageUrl: "/images/tipps/fell-haut/19.jpg",
    imageAlt: "Hundebürste wird unter Wasser gereinigt und von Haaren befreit",
    content: `Hundebürsten werden benutzt — selten gereinigt. Dabei sind sie nach einigen Bürstvorgängen voller lose Haare, Hautschuppen, Talg, Schmutz und potenziell Floheiern oder Pilzsporen. **Eine schmutzige Bürste ist kein Pflegewerkzeug mehr — sie ist ein Keimverteiler.**

## Was sich in einer ungepflegten Bürste ansammelt

- **Lose Haare** aus dem Fell — die Bürste verliert ihre Wirksamkeit
- **Hautschuppen und Talg** — ideale Nährlösung für Bakterien und Pilze
- **Flöheier** — fallen zwischen die Borsten und werden verteilt
- **Pilzsporen** — bei Hautpilz werden Sporen bei jedem Bürstvorgang im Fell verteilt
- **Pflegeproduktreste** — verkleben die Borsten

## Reinigung der Bürste — Schritt für Schritt

### 1. Haare entfernen
Nach jedem Bürstvorgang die gesammelten Haare aus den Borsten nehmen. Ein alter Kamm, eine Schere oder ein spezieller Bürstenreiniger helfen dabei.

### 2. Bürste auswaschen
Wöchentlich:
- Bürste in lauwarmem Wasser einweichen (bei Naturbürsten kurz, bei Plastik länger)
- Mit einem Tropfen mildem Hundeshampoo oder Spülmittel die Borsten sanft waschen
- Gut abspülen
- Liegend trocknen lassen (nicht auf dem Holzrücken stehend — das quillt auf)

### 3. Desinfektion bei Bedarf
Bei Parasitenbefall oder Hautpilz:
- Plastik- und Metallbürsten in verdünnte Desinfektionslösung einlegen (10 Minuten)
- Naturbürsten im Zweifel wegwerfen — Sporen überleben im Naturmaterial

## Verschiedene Bürsten — verschiedene Pflege

| Bürste | Häufigkeit | Methode |
|---|---|---|
| Slicker Brush (Metall) | Wöchentlich | Waschen + gelegentlich desinfizieren |
| Unterwollkamm | Wöchentlich | Haare entfernen + waschen |
| Gummibürste | Wöchentlich | Waschen, leicht |
| Naturbürste | 2-wöchentlich | Schonend waschen, kurz |
| Trimmmesser | Nach Gebrauch | Trocken abwischen, Klingen ölen |

## Wann Bürsten ersetzt werden sollten

- Verbogene oder fehlende Borsten, die beim Bürsten ziehen
- Nach einem Parasitenbefall oder einer Pilzerkrankung (bei Naturbürsten)
- Bei sichtbarem Rost an Metallbürsten

## Häufige Fragen

### Kann ich die Bürste in der Spülmaschine waschen?
Bei Plastikbürsten ohne Holzgriff oft ja — aber auf niedriger Temperatur. Naturbürsten und Holzgriffe nicht in die Spülmaschine.

### Wie lange hält eine gute Hundebürste?
Bei regelmäßiger Reinigung viele Jahre. Günstige Bürsten verbiegen sich oft schnell.

## Das Wichtigste in Kürze

- Bürsten nach jedem Einsatz von losen Haaren befreien
- Wöchentlich waschen — Naturbürsten schonend, Plastik kann länger eingeweicht werden
- Bei Parasiten oder Pilz: Plastikbürsten desinfizieren, Naturbürsten ersetzen
- Verbogene oder rostende Bürsten ersetzen`,
