    keywords: ["hund vor bad bürsten", "verfilzungen hund nass", "hund waschen vorbereitung", "hund fell bürsten vor bad", "hund kämmen verfilzungen"],
    geoRelevant: false,
    internalLinks: ["/tipps/gesundheit", "/tipps/ernaehrung", "/"],
    relatedTips: [61, 63, 8],
