    imageUrl: "/images/tipps/fell-haut/9.jpg",
    imageAlt: "Hund liegt im Sommer im Schatten und wird gebürstet",
    content: `Während der Winter vor allem Ballen und Haut durch Kälte und Salz beansprucht, bringt der Sommer seine ganz eigenen Herausforderungen mit. Wer die Pflegeroutine saisonal anpasst, beugt vielen typischen Sommerproblemen effektiv vor.

## Die größten sommerlichen Pflegethemen

### Grannen
Grannen — die scharfen, nadelartigen Früchte verschiedener Wildgräser — sind im Sommer der gefährlichste Fremdkörper im Fell. Sie wandern aktiv ins Fell hinein, bohren sich durch die Haut und können Abszesse verursachen.

Nach jedem Spaziergang durch hohes Gras oder Gebüsch solltest du das Fell **gründlich absuchen**:
- Besondere Aufmerksamkeit: zwischen den Zehen, in den Ohren, Achseln und Leiste
- Bei Hunden mit langem Fell: die Bereiche aktiv auseinandernehmen, nicht nur drüberstreifen
- Eine eingebettete Granne, die sich nicht herausziehen lässt, gehört sofort zum Tierarzt

### Zecken
Im Sommer sind Zecken ganzjährig aktiv — mit Hochsaison von April bis Oktober. Dichte, ungepflegte Felle bieten Zecken bessere Versteckmöglichkeiten. Tägliche Kontrolle nach Spaziergängen, besonders in Wäldern und Wiesen, ist Pflicht.

### Hitzestau im Fell
Doppelhaarige Rassen (Husky, Malinois, Golden Retriever) werden manchmal im Sommer geschoren, um sie zu kühlen. Das ist ein Fehler: Die **Unterwolle isoliert in beide Richtungen** — sie hält Wärme draußen und kühlt gleichzeitig. Stattdessen:

- Unterwolle gründlich mit dem Unterwollkamm entfernen
- Fell luftig ausbürsten
- Schatten und frisches Wasser anbieten

Das Scheren zerstört die Schutzfunktion des Fells dauerhaft bei manchen Rassen.

## Die sommerliche Pflegefrequenz erhöhen

Im Sommer sammelst du in kürzerer Zeit mehr Schmutz, Pollen und Parasiten ein. Es lohnt sich, die Bürstfrequenz anzupassen:

- Bei kurzen Fellen: zwei- bis dreimal pro Woche
- Bei mittleren und langen Fellen: täglich oder jeden zweiten Tag
- Nach Spaziergängen in hohem Gras oder Wald: immer direkt danach suchen

## Haut und Sonne bedenken

Hunde mit dünnem Fell, heller Haut oder an spärlich behaarten Körperstellen (Nase, Ohren, Bauch) können einen Sonnenbrand bekommen. Besonders gefährdet: weiße Hunde und solche mit rosafarbener Haut.

- Mittagshitze zwischen 11 und 15 Uhr meiden
- Schattige Spazierwege bevorzugen
- Bei sehr empfindlicher Haut: tierärztlich verträglichen Sonnenschutz verwenden

## Baden im Sommer: Häufigkeit beachten

Im Sommer ist die Versuchung groß, den Hund öfter zu waschen. Das ist aber nur bei echtem Schmutz nötig. Häufiges Baden im Sommer in Verbindung mit Chlor- oder Salzwasser kann die Haut austrocknen. Nach dem Schwimmen: immer mit klarem Wasser abspülen.

## Häufige Fragen

### Darf ich meinen Husky im Sommer scheren, damit er nicht überhitzt?
Nein. Das Fell schützt auch vor Überhitzung. Stattdessen Unterwolle ausgiebig ausbürsten und für ausreichend Schatten und Wasser sorgen.

### Wie erkenne ich eine eingewanderte Granne?
Anschwellungen, Abszesse oder eine kleine rote Einstichstelle am Körper, oft zwischen den Zehen. Sofort zum Tierarzt.

## Das Wichtigste in Kürze

- Grannen nach Spaziergängen aktiv suchen — besonders zwischen Zehen und in Ohren
- Doppelhaarige Hunde nicht scheren — Unterwolle ausbürsten reicht
- Tägliche Zeckenkontrolle im Sommer
- Helle Hunde vor starker Sonneneinstrahlung schützen`,
