    title: "Bei Schilddrüsenproblemen ans Fell denken",
    shortDescription:
      "Stumpfes, ausdünnendes Fell kann auf Hypothyreose hindeuten. Ein Bluttest bringt Klarheit.",
    level: 2,
    tags: ["schilddruese", "fell"],
    imageUrl: "/images/tipps/fell-haut/17.jpg",
    imageAlt: "Tierarzt nimmt einem Hund Blut für einen Schilddrüsentest ab",
    content: `Wenn das Fell deines Hundes allmählich dünner wird, stumpfer aussieht und keine der üblichen Maßnahmen helfen, lohnt ein Blick auf die Schilddrüse. Die Schilddrüsenunterfunktion (Hypothyreose) ist eine der häufigsten hormonellen Erkrankungen beim Hund — und sie zeigt sich oft zuerst am Fell.

## Was ist Hypothyreose beim Hund?

Die Schilddrüse produziert Hormone, die den gesamten Stoffwechsel regulieren. Bei einer Unterfunktion (Hypothyreose) werden zu wenig dieser Hormone produziert — und das spürt der ganze Körper.

Betroffene Rassen: Besonders häufig bei Golden Retriever, Dobermann, Labrador, Irischer Setter und Boxern, aber grundsätzlich bei jeder Rasse möglich.

Mittleres Erkrankungsalter: oft zwischen 4 und 10 Jahren.

## Fellveränderungen bei Hypothyreose

Das Fell ist oft eines der ersten Organe, das auf die Schilddrüsenunterfunktion aufmerksam macht:

- **Ausdünnendes Fell**, besonders am Rumpf und an der Rute
- **Stumpfes, raues Fell** ohne Glanz
- **Schlechte Haarqualität** — Haare brechen leicht
- **Symmetrischer Haarausfall** ohne Juckreiz (unterscheidet sich von Allergie- oder Parasitenbefall)
- Die Haut darunter kann verdickt oder schuppig wirken

Typisch: Das Fell fällt aus, wächst aber nicht oder nur langsam nach.

## Begleitsymptome, die den Verdacht erhärten

Fellveränderungen allein reichen nicht für eine Diagnose. Hypothyreose geht oft einher mit:

- **Gewichtszunahme** trotz normaler Fütterung
- **Lethargie** — der Hund wirkt antriebslos, schläft mehr
- **Kälteempfindlichkeit** — der Hund sucht Wärme, auch im Sommer
- **Verlangsamte Herzfrequenz**
- **Hautverdickungen** an bestimmten Körperstellen

Das Zusammentreffen mehrerer dieser Symptome ist ein deutliches Signal für eine tierärztliche Untersuchung.

## Diagnose und Behandlung

Die Diagnose erfolgt über einen **Bluttest**: Messung von T4 (Thyroxin) und TSH (Schilddrüsen-stimulierendes Hormon). Der Tierarzt kann auch ein erweitertes Schilddrüsenprofil anfordern, da Standardwerte manchmal uneindeutig sind.

Die Behandlung ist gut möglich: Die meisten Hunde erhalten **täglich L-Thyroxin** als Tablette. Die Dosis wird anhand von Kontrollbluttests angepasst. Nach Therapiebeginn verbessern sich Fell, Energie und Gewicht oft innerhalb weniger Monate deutlich.

## Was du als Halter tun kannst

- Beobachte Fell, Gewicht und Verhalten über Zeit — halte Veränderungen fest
- Sprich den Tierarzt aktiv auf die Symptomkombination an
- Lass dich nicht mit „Alter" oder „Jahreszeit" abspeisen, wenn die Symptome sich häufen
- Nach Diagnose: Kontrolltermine wahrnehmen, da die Dosierung angepasst werden muss

## Häufige Fragen

### Kann mein Hund mit Hypothyreose normal leben?
Ja, mit regelmäßiger Medikation und Kontrollen ist die Lebensqualität in der Regel sehr gut.

### Gibt es einen Zusammenhang mit Futterallergien?
Hypothyreose und Allergien können gleichzeitig vorkommen. Eine Schilddrüsenunterfunktion kann die Immunfunktion beeinflussen und Allergiesymptome verstärken.

## Das Wichtigste in Kürze

- Symmetrischer Haarausfall ohne Juckreiz plus Trägheit und Gewichtszunahme: Schilddrüse prüfen
- Diagnose über Bluttest beim Tierarzt
- Behandlung mit täglich L-Thyroxin ist gut möglich
- Mit Therapie verbessert sich das Fell meist innerhalb von Monaten deutlich`,
