    id: 75,
    slug: "hormonellen-haarausfall-erkennen",
    title: "Hormonellen Haarausfall erkennen",
    shortDescription:
      "Symmetrischer Haarausfall ohne Juckreiz hat oft hormonelle Ursachen. Solche Muster gehören tierärztlich untersucht.",
    level: 2,
    tags: ["hormone", "haarausfall"],
    imageUrl: "/images/tipps/fell-haut/18.jpg",
    imageAlt: "Tierarzt untersucht einen Hund mit symmetrischem Haarausfall",
    content: `Nicht jeder Haarausfall beim Hund ist gleich. Es gibt Muster, die auf bestimmte Ursachen hinweisen — und keines ist so charakteristisch wie der **symmetrische Haarausfall ohne Juckreiz**. Dieses Muster ist ein typisches Zeichen hormoneller Störungen, das erkannt und ernst genommen werden sollte.

## Was symmetrischer Haarausfall bedeutet

Hormonelle Erkrankungen betreffen den ganzen Körper gleichmäßig. Deshalb zeigt sich Haarausfall bei diesen Ursachen oft **beidseitig und gleichmäßig** — das heißt: beide Flanken, beide Oberschenkel, beide Seiten des Rumpfes verlieren gleichzeitig Haar.

Das unterscheidet ihn klar von:
- Parasitenbefall: oft fleckig, mit Juckreiz, unregelmäßig verteilt
- Pilzinfektionen: runde, schuppige Stellen, oft mit Entzündung
- Allergien: Juckreiz steht im Vordergrund, besonders an Pfoten, Bauch, Ohren
- Mechanischer Reizung: lokal begrenzt an Kontaktstellen

## Hormonelle Ursachen des Haarausfalls

### Hypothyreose (Schilddrüsenunterfunktion)
Die häufigste hormonelle Ursache. Begleitet von Gewichtszunahme, Trägheit und Kälteempfindlichkeit. Bluttest klärt ab.

### Cushing-Syndrom (Hyperadrenokortizismus)
Überschuss an Kortisol, produziert von der Nebennierenrinde. Typische Zeichen: dünnes Fell, dicker Bauch, gesteigerter Durst und Hunger, Muskelschwäche. Diagnose erfordert spezifische Bluttests.

### Sexualhormonstörungen
Bei nicht kastrierten Hunden können Sexualhormone den Fellzyklus beeinflussen. Auch nach Kastration kann es vorübergehend zu hormonellen Fellveränderungen kommen (sogenannte Kastrationshypothyreose oder „Post-Kastrations-Alopezie").

### Wachstumshormonmangel
Seltenere Ursache, besonders bei bestimmten Rassen. Führt zu beidseitigem, symmetrischem Haarausfall ohne andere deutliche Symptome.

## Was du beobachten und festhalten solltest

Vor dem Tierarzttermin lohnt es sich:

- Die betroffenen Körperstellen genau beschreiben und fotografieren
- Begleitende Symptome notieren: Gewicht, Aktivität, Durst, Hunger
- Zeitraum festhalten: Wann begann der Haarausfall?
- Weitere Veränderungen: Haut verdickt, Pigmentveränderungen?

Diese Infos helfen dem Tierarzt, gezielt die richtigen Tests anzuordnen.

## Diagnose und Behandlung

Der Tierarzt wird je nach Verdacht unterschiedliche Tests anordnen:

- **Blutbild und Hormonstatus** für Schilddrüse und Kortisol
- **ACTH-Stimulationstest** oder **Dexamethason-Suppressionstest** bei Cushingverdacht
- **Bildgebung** (Ultraschall) zur Beurteilung der Nebennieren

Die Behandlung hängt von der Ursache ab:
- Hypothyreose: tägliche Hormonersatztherapie (L-Thyroxin)
- Cushing: Medikamentöse Therapie oder Operation je nach Ursache

## Häufige Fragen

### Kann ich hormonellen Haarausfall mit besserer Ernährung lösen?
Nein. Hormonelle Erkrankungen brauchen medizinische Diagnose und Therapie. Ernährung kann unterstützen, ist aber keine Ursachenbehandlung.

### Wie lange dauert es, bis das Fell nach Behandlungsbeginn nachwächst?
Bei Hypothyreose sind erste Verbesserungen nach zwei bis vier Monaten zu erwarten, das volle Ergebnis nach sechs bis zwölf Monaten.

## Das Wichtigste in Kürze

- Symmetrischer Haarausfall ohne Juckreiz ist ein typisches Zeichen hormoneller Störung
- Wichtigste Ursachen: Hypothyreose, Cushing, Sexualhormonstörungen
- Diagnose über tierärztliche Bluttests
- Ohne Behandlung verschlimmert sich das Fell — frühe Diagnose lohnt`,
