    title: "Den Hundefriseur sinnvoll einsetzen",
    shortDescription:
      "Bei pflegeintensiven Rassen entlastet ein guter Hundefriseur spürbar und beugt Verfilzungen vor. Regelmäßige Termine lohnen sich.",
    level: 1,
