    tags: ["fellwechsel", "ernaehrung"],
    imageUrl: "/images/tipps/fell-haut/7.jpg",
    imageAlt: "Hund wird während des Fellwechsels mit einem Unterwollkamm gebürstet",
    content: `Zweimal im Jahr — im Frühjahr und Herbst — findet beim Hund der Fellwechsel statt. Altes Fell wird abgestoßen, neues Haar wächst nach. Dieser Prozess ist energieintensiv und stellt erhöhte Anforderungen an die Nährstoffversorgung. Wer das berücksichtigt, unterstützt den Neuwuchs aktiv.

## Was beim Fellwechsel im Körper passiert

Haare bestehen zu einem Großteil aus Keratin — einem Strukturprotein. Beim Fellwechsel werden nicht nur alte Haare verloren, es werden auch in kurzer Zeit sehr viele neue Haare gebildet. Das verbraucht:

- **Protein und Aminosäuren** (besonders Cystein, Methionin, Lysin)
- **Omega-Fettsäuren** für gesunde Haarstruktur und Haut
- **Zink** für die Zellteilung in den Haarfollikeln
- **Biotin** und **B-Vitamine** für Keratinproduktion
- **Eisen** für die Haarwurzelversorgung

Bei hochwertiger Basisernährung ist der Mehrbedarf oft gedeckt. Bei günstigeren oder nährstoffärmeren Futtern kann der Fellwechsel länger dauern und das Ergebnis schlechter ausfallen.

## Woran du einen schleppenden Fellwechsel erkennst

- Das Haaren dauert deutlich länger als gewöhnlich (mehr als sechs bis acht Wochen)
- Das neue Fell wirkt dünn, glanzlos oder wächst ungleichmäßig
- Die Haut darunter wirkt schuppig oder gereizt
- Der Hund wirkt matter als sonst

Das allein ist kein Alarm — aber ein Hinweis, die Ernährung zu überdenken.

## Was du ernährungsseitig tun kannst

### Hochwertige Proteinquelle sicherstellen
Gerade während des Fellwechsels sollte das Futter eine klare, tierische Proteinquelle als Hauptbestandteil haben. Hühnchen, Rind, Lachs, Lamm — die Quelle ist weniger wichtig als die Qualität und der Anteil im Futter.

### Omega-Fettsäuren ergänzen
Lachsöl (1–2 TL täglich je nach Größe) ist eine bewährte Ergänzung während des Fellwechsels. Es liefert EPA und DHA direkt, die Haut und Haarstruktur unterstützen.

### Biotin gezielt ergänzen
Biotin (Vitamin B7) spielt eine direkte Rolle bei der Keratinbildung. Es ist in Bierhefe, Leber und Ei enthalten — oder als Ergänzungsmittel erhältlich. Rücksprache mit dem Tierarzt ist empfehlenswert.

### Ausreichend Wasser
Gutes Haarwachstum braucht eine gut hydratisierte Haut. Stell sicher, dass dein Hund während des Fellwechsels ausreichend trinkt.

## Bürsten als unterstützende Maßnahme

Ernährung und Bürsten arbeiten zusammen. Regelmäßiges Ausbürsten:
- Entfernt lose Haare, die das Nachwachsen behindern
- Stimuliert die Durchblutung der Haut und der Haarfollikel
- Verhindert, dass abgestorbene Unterwolle Hitzestau verursacht

Während des Fellwechsels täglich oder alle zwei Tage bürsten — bei starker Unterwolle mit einem Unterwollkamm.

## Häufige Fragen

### Kann ich das Haaren mit Nahrungsergänzungsmitteln reduzieren?
Nein — der Fellwechsel ist ein physiologischer Prozess, der nicht unterdrückt werden sollte. Gute Ernährung unterstützt ihn und lässt ihn schneller und gleichmäßiger ablaufen, aber stoppt ihn nicht.

### Mein Hund haart das ganze Jahr — was ist das?
Bei Hunden in Innenräumen mit Heizung kann der klassische saisonale Fellwechsel verschwimmen, und sie haaren ganzjährig. Regelmäßiges Bürsten und eine gute Grundernährung helfen.

## Das Wichtigste in Kürze

- Fellwechsel braucht erhöhte Protein-, Fettsäuren- und Mikronährstoffversorgung
- Omega-Fettsäuren (Lachsöl) und Biotin können den Neuwuchs unterstützen
- Hochwertige tierische Proteinquelle im Grundfutter ist Pflicht
- Regelmäßiges Bürsten während des Fellwechsels ist eine sinnvolle Ergänzung`,
