    content: `Wenn dein Hund Hautprobleme hat, ist die Versuchung groß, selbst zu handeln. Online gibt es viele Empfehlungen — von Kokosnussöl über Teebaumöl bis hin zu Babyshampoo. Das Problem: Nicht alles, was bei Menschen funktioniert oder gut klingt, ist für Hunde geeignet — und manches ist direkt schädlich.

## Warum Hundehaut andere Anforderungen hat

Hundehaut unterscheidet sich von Menschenhaut in mehreren relevanten Punkten:

- **pH-Wert**: Die Hundehaut hat einen pH-Wert von etwa 6,5–7,5 (nahezu neutral), Menschenhaut liegt bei 4,5–5,5 (leicht sauer). Menschenprodukte sind auf den sauren pH abgestimmt — sie können die Hautflora des Hundes destabilisieren.
- **Dünnere Epidermis**: Die Hundehaut ist dünner und empfindlicher. Inhaltsstoffe dringen leichter ein.
- **Lecken**: Hunde lecken sich — was auf die Haut kommt, landet im Maul. Manche Inhaltsstoffe sind für Menschen unbedenklich, aber für Hunde bei oraler Aufnahme giftig.

## Häufig verwendete Mittel, die schaden können

### Teebaumöl
Weit verbreitet als „natürliches Mittel" — ist aber für Hunde giftig, auch in kleinen Mengen auf der Haut. Wird abgeleckt und kann zu ernsthaften Vergiftungen führen.

### Babypuder und Stärke
Werden manchmal in Hautfalten empfohlen — tatsächlich können sie Entzündungen fördern, da feuchte Umgebung mit Puder zu Verklebungen führt.

### Essig und Zitronensaft
Säuren stören den Hautmantel des Hundes und reizen entzündete Haut zusätzlich.

### Menschenshampoos (auch „sensitiv" oder „mild")
Falscher pH-Wert, oft Duftstoffe und Konservierungsmittel, die für Hunde nicht geeignet sind.

### Zinkoxid-Cremes (wie Wundschutzcreme)
Zinkoxid ist für Hunde in größeren Mengen giftig. Hunde lecken sich ab — Vorsicht bei jeglichen Cremes mit Zinkoxid.

## Was stattdessen hilft

Bei Hautproblemen:
- **Mildes, hundespezifisches Shampoo** — ohne Sulfate, Duftstoffe oder Konservierungsstoffe
- **Pflegeprodukte mit Haferextrakt** — beruhigen empfindliche Haut sanft
- **Tierärztlich empfohlene Lösungen** je nach Ursache — antibakteriell, antifungal oder beruhigend
- **Keine Eigentherapie** bei offenen Wunden, Entzündungen oder unklaren Hautveränderungen

Der Tierarzt kann die Ursache der Hautprobleme klären und geeignete Produkte empfehlen — das ist effizienter als Ausprobieren.

## Wenn du ein neues Produkt ausprobieren möchtest

Unbekannte Produkte immer zuerst an einer kleinen Stelle testen:
1. Kleine Menge auf eine unauffällige Hautstelle auftragen
2. 24 Stunden beobachten
3. Rötung, Schwellung oder Juckreiz? Produkt sofort abwaschen

## Häufige Fragen

### Was ist mit Kokosöl?
Kokosöl ist für Hunde ungiftig und kann äußerlich für trockene Ballen oder leicht rissige Stellen verwendet werden. Es ist aber kein Allheilmittel für Hauterkrankungen.

### Ich habe Produkte online gekauft, die für Hunde beworben werden — sind die sicher?
Nicht automatisch. Achte auf Zertifizierungen und Inhaltslisten. Im Zweifelsfall beim Tierarzt nachfragen.

## Das Wichtigste in Kürze

- Menschenprodukte haben den falschen pH-Wert für Hundehaut
- Teebaumöl und Zinkoxid sind für Hunde giftig — Finger weg
- Tierärztlich empfohlene Produkte sind der sichere Weg
- Bei Eigenversuchen: kleiner Hauttest zuerst, immer beobachten`,
