    imageUrl: "/images/tipps/fell-haut/1.jpg",
    imageAlt: "Hund im Jahreswechsel — Sommer und Winter nebeneinander",
    content: `Die Pflegeroutine, die im Sommer funktioniert, ist im Winter eine andere. Und was im Fellwechsel hilft, ist im ruhigen Sommermonat übertrieben. Wer die Pflege seines Hundes an die Jahreszeiten anpasst, arbeitet mit dem Körper des Hundes — nicht dagegen.

## Frühling: Der große Fellwechsel

Der Frühling bringt den stärksten Fellwechsel des Jahres. Unterwolle, die über den Winter gedient hat, wird abgestoßen — manchmal in beeindruckenden Mengen.

**Pflege-Anpassungen im Frühling:**
- Bürstfrequenz erhöhen — täglich oder jeden zweiten Tag
- Unterwollkamm einsetzen bei Doppelhaarrassen
- Frühlingspollen im Blick haben: Hunde mit Atopie bekommen in dieser Phase oft mehr Juckreiz
- Haut nach dem Fellwechsel gut beobachten — verändert sie sich?

## Sommer: Grannen, Zecken, Hitzeschutz

Hohe Temperaturen und dichtes Gras bringen eigene Herausforderungen.

**Pflege-Anpassungen im Sommer:**
- Nach jedem Spaziergang Grannen suchen — besonders zwischen Zehen, in Ohren und Achseln
- Tägliche Zeckenkontrolle nach Waldläufen
- Doppelhaarrassen nicht scheren — Unterwolle ausbürsten stattdessen
- Haut nach intensivem Sonnenkontakt kontrollieren
- Nach Schwimmen immer abspülen und trocknen

## Herbst: Zweiter Fellwechsel und Vorbereitung

Der Herbst bringt den zweiten Fellwechsel — Winterfell wächst nach. Gleichzeitig wird es nasser und schlammiger.

**Pflege-Anpassungen im Herbst:**
- Wieder mehr bürsten, Fellwechsel unterstützen
- Pfoten nach Spaziergängen öfter abtrocknen — nasse Füße begünstigen Hefepilz
- Pfotenbalsam beginnen aufzutragen, bevor der Winter kommt
- Dichtes Fell auf Trockenheit prüfen: Beginn der Heizperiode trocknet aus

## Winter: Kälte, Salz und Heizungsluft

Winter kombiniert äußere Kälte mit trockener Innenluft — eine Doppelbelastung für die Haut.

**Pflege-Anpassungen im Winter:**
- Pfoten nach Spaziergängen auf Streusalz abspülen
- Pfotenbalsam vor und nach Winterspaziergängen
- Fettsäureversorgung prüfen: Haut wird trockener
- Auf Schuppen achten — häufig saisonales Zeichen
- Felltrocknung nach nassen Spaziergängen nicht vergessen

## Das Grundprinzip

Keine Jahreszeit braucht aufwendige Spezialroutinen — es geht um Aufmerksamkeit und kleine Anpassungen. Wer seinem Hund regelmäßig zuschaut und Veränderungen bemerkt, passt sich automatisch an.

## Häufige Fragen

### Wie erkenne ich, welche Jahreszeit gerade Probleme verursacht?
Achte auf den Timing: Tritt das Problem immer im gleichen Monat auf? Dann ist der saisonale Zusammenhang wahrscheinlich.

### Muss ich im Winter mehr bürsten als im Sommer?
Nicht zwingend mehr — aber die Haut öfter auf Trockenheit und Schuppen kontrollieren. Dichtes Winterfell braucht gute Pflege, um Feuchtigkeit nicht einzuschließen.

## Das Wichtigste in Kürze

- Jede Jahreszeit bringt eigene Pflegeschwerpunkte
- Frühling und Herbst: Fellwechsel intensiv bürsten
- Sommer: Grannen, Zecken, Hitzeschutz
- Winter: Streusalz, Trockenheit, Pfotenpflege`,
    seoTitle: "Hundepflege durch die Jahreszeiten: Was sich wann verändert | BELLA",
